// the segment). Two 170BG at TEB 2.55 bar make the raw difference uncertain by +/-5.1 bar (RSS 3.6), so the zero is captured in situ
// with no flow: PREPRESS (MV OPEN, pintle seated) and COAST 0.2-0.4 s after entry (MV just closed, segment still at P_tank).
constexpr float kS1DpMax_Pa = 2.0e5f;              // [COMB/LEAD 2026-10-13]
constexpr float kS1Time_s = 1.0f;                  // [COMB/LEAD 2026-10-13]
constexpr float kS1ZeroMax_Pa = 5.1e5f;            // [DERIVED 2 x TEB 2.55 bar] a larger zero = transducer fault (not accepted)
constexpr int kS1ZeroN = 20;                       // [DESIGN] samples per zero block (1 kHz, filtered pressures)
constexpr float kS1ZeroMvOpen_s = 0.050f;          // [DESIGN] PREPRESS: OPEN switch made this long before sampling
constexpr float kS1CoastZeroFrom_s = 0.20f;        // [DESIGN] COAST zero window start (from COAST entry) ...
constexpr float kS1CoastZeroTo_s = 0.40f;          // [DESIGN] ... and end
constexpr bool kS1LockoutStand = true;             // [LEAD 2026-10-13] stand: S1 fault -> relight lockout
constexpr bool kS1LockoutFlight = false;           // [LEAD 2026-10-13] flight: flag and log only, the relight proceeds
// v2.8.1 over-thrust (LEAD 2026-10-13 ADOPTED on GNC m2_fc_thrust v1.1, gnc_v3.1_staging.json 695a069e8fc8dc53): the FC sends its
// first-order (tau 20 ms) accelerometer thrust estimate in FC_THRUST at kFcThrustRate_Hz; the frame's valid flag is set by the FC only
// when airborne, engine lit and with NO DROGUE LOAD (LEAD 2026-10-13 line 111 (6); the v2.8.1-v2.8.3 comments said "drogue released").
// ECU rule: flight mode, state RUN, kOverThrustFrames CONSECUTIVE fresh frames with the
// valid flag above kOverThrust_N -> OVER_THRUST (3 frames = a 20 ms span at 100 Hz, GNC's rule; a frame at or below the threshold, an
// invalid frame, a gap above kFcThrustStale_s or leaving RUN restarts the count). v2.8.1: the check runs whether or not the Pc channel
// is valid (v2.8: Pc lost only) - it also covers an in-range but wrong Pc reading in closed loop (sense-line blockage, zero shift),
// which the Pc-based over-pressure checks cannot see; GNC: 0/1000 healthy false aborts at >= 610 N (SIM). Basis 500 N x (Cd 0.8/0.7 =
// 1.143) x 1.10 = 628 N -> 650 N (~32.1 bar abs equivalent). Blind to throat blockage (thrust falls while Pc rises). Stale or invalid
// estimate: no check (flag only: log seq2_flags b4 clear, fc_thr_dN 0xFFFF).
constexpr float kOverThrust_N = 650.0f;            // [LEAD 2026-10-13 ADOPTED]
constexpr int kOverThrustFrames = 3;               // [LEAD 2026-10-13 ADOPTED] consecutive frames above the threshold
constexpr float kFcThrustRate_Hz = 100.0f;         // [GNC m2_fc_thrust v1.1 / LEAD] FC_THRUST frame rate (interface requirement)
constexpr float kOverThrustTime_s = 0.020f;        // [LEAD 2026-10-13] hold span of the frame rule at kFcThrustRate_Hz (documentation;
                                                   //   the ECU counts frames; calc/over_thrust_v2.py reads it)
static_assert((kOverThrustFrames - 1) / kFcThrustRate_Hz > kOverThrustTime_s - 1e-4f && (kOverThrustFrames - 1) / kFcThrustRate_Hz < kOverThrustTime_s + 1e-4f,
              "frame count and hold span disagree at the FC_THRUST rate");
constexpr float kFcThrustStale_s = 0.050f;         // [GNC decision 2026-10-13] older estimate = not fresh (5 frame periods at 100 Hz)
// Normal shutdown (RC-01 abort matrix): pintle first, NC valve after the seat is confirmed or the timeout, whichever first. Every
// ABORT de-energises the NC valve at once (enter(ABORT)) with the pintle commanded closed in parallel.
constexpr float kPintleSeatConfirm_m = 0.05e-3f;   // [DESIGN] encoder lift at or below this ...
constexpr int kSeatConfirmN = 5;                   // [DESIGN] ... for 5 consecutive ticks = seated
// v2.8.2 (GNC REV-GNC-1 RG-08): pintle-position anomaly in COAST. With the NC valve closed the valve-to-seat segment can only lose its
// liquid through the pintle seat; a needle off the seat lets it flash into the vented chamber while P_feed stays near P_sat (the pressure
// rule cannot see saturated vapour: RG-01). Encoder invalid on any COAST tick -> UNKNOWN; encoder lift above kCoastPintleOpen_m for
// kCoastPintleOpenN consecutive COAST ticks -> UNPRIMED. Both latch (RAM) until the next confirmed light (RUN entry) or DISARM in SAFE
// and force the prep path; the path and TLM_RELIGHT use the same latches. Values to be set at B-PNT-1 (encoder noise, zero drift over
// the coast soak-back, needle bounce at the drogue shock).
constexpr float kCoastPintleOpen_m = 2.0f * kPintleSeatConfirm_m;   // [DESIGN] 0.10 mm: 2 x the seat-confirm lift (encoder noise margin)
constexpr int kCoastPintleOpenN = 20;              // [DESIGN] 20 consecutive 1 ms ticks (rejects a shock bounce of a few ms)
static_assert(kCoastPintleOpen_m < kPintleStallErr_m, "the coast anomaly must flag below the stall-monitor error (which aborts)");
constexpr float kMvSeatTimeout_s = 0.30f;          // [COMB v2.4 / LEAD 2026-10-13; v2.7-v2.8 draft 0.25 DESIGN] NC valve unlatched regardless
                                                   //   this long after SHUTDOWN entry (fault PINTLE if the encoder was valid). A planned
                                                   //   cut-off (MECO, landing cut = Cmd::SHUTDOWN) never calls the abort path: only a
                                                   //   fault monitor (over-pressure, pintle stall / rail loss, ARM chain) or an FC ABORT /
                                                   //   DISARM does (test_v28 group 16). An abort with the 30 ms MV-P leaves the segment
                                                   //   about 50 % vapour (COMB v2.4), the pintle-first shutdown keeps it liquid
static_assert(kMvSeatTimeout_s >= 1.4f * kPintleCloseSlow_s, "seat timeout too close to the slowest powered closing");
static_assert(kMvSeatTimeout_s < kShutdownTimeout_s, "the valve must be unlatched before SHUTDOWN can time out");
// No automatic in-flight relight retry (LEAD 2026-10-13): an abort from IGNITION, RUN or SHUTDOWN after a lit burn in this power
// cycle or on a relight (start >= 2) sets the relight lockout: ARM, IGNITE and RELIGHT are refused (RELIGHT_LOCKOUT) until a keyed
// CLEAR_LOCKOUT in SAFE (ground). The HAL keeps it non-volatile (NvJamRecord flags b1) so an ECU reset in flight cannot clear it.
// v2.10 (LEAD 172 (1)): a GROUND no-light (stand any start, pad first start) also sets the lockout and opens the safing hold
// (kNoLightSafingMin_s before CLEAR_LOCKOUT is accepted). The v2.5-v2.9 first-start retry after 5 s is withdrawn.
constexpr uint16_t kClearLockoutKey = 0x10C7;      // [DESIGN] CLEAR_LOCKOUT argument, accepted in SAFE only
// Pintle rail loss (LEAD 2026-10-13: an LTC4365 OV-disconnect trip reaches the ECU and is handled as PINTLE_FAULT -> ABORT). Two
// paths: hardware (LTC4365 /FAULT low gates the MV holding-magnet driver off, independent of this code) and firmware (rail sensed
// on the servo side of the disconnect, ADC2 CH1).
constexpr float kPrailLost_V = 5.5f;               // [DESIGN] servo-side rail below this = lost (HV69 rated 6.0-8.4 V (retailer
                                                   //   copies of MKS data); setpoint 7.49 V, UV of the LTC4365 set at ~5.0 V)
constexpr float kPrailLostTime_s = 0.002f;         // [DESIGN] persistence (2 ADC frames)
constexpr float kPrailSettle_s = 0.060f;           // [DESIGN] ignored this long after the ARM bus comes on: LTC4365 recovery delay
                                                   //   <= 49 ms (DS LTC4365 rev B, 36 ms typ; a start-up delay of the same kind is
                                                   //   ASSUMED) + TPS552882 soft start <= 5 ms (DS)
// Pc-sensor loss in RUN: in flight the burn continues open loop on the map (fault OPEN_LOOP; the landing burn is not thrown away);
// on the test stand (v2.8: stand mode = strap AND finite load cell, latched at ARM) it aborts (PC_SENSOR).
constexpr float kPcSensorLossStand_s = 0.005f;     // [DESIGN] persistence of the stand abort

// ---------------------------------------------------------------- v2.9 light detection: RELATIVE rule (LEAD 2026-10-13, ADOPTED)
// LEAD 2026-10-13 CHANGELOG line 134, adopting Combustion ignition_detect_v2p4.json (a34b05c90499badb, SIM grain_q1d v2 on ASSUMED laws;
// IGN-1 and T1 measure the real values). Supersedes the Electronics (B) proposal of the same day (post-lift baseline window, +0.5 bar,
// 5 ticks: a window after E1 would have to close by ~E1 + 0.07 s, before the 0.079 s earliest light, while the cold-flow Pc is still
// building) and the absolute 3.0 bar abs rule of v2.6-v2.8.3 (kIgnitionPcAbs WITHDRAWN).
//   Baseline P0 = mean of the last kIgnPreN ticks up to E1 (the ignition-lift command), torch lit, pintle seated: no main N2O enters
//     before E1 (no main N2O; an OFFSET needs no N2O: EMI, ground shift, drift, sensor fault - REV-ELEC-1 RE-02); filtered and raw (1 kHz
//     decimated, zeroed) gauge Pc. Checked against the auto-zero ambient (v2.10, LEAD RE-02, one-sided): P0 > +kIgnBaseCheck_Pa -> the
//     MEASURED P0 is kept and BASE_HIGH flagged to the FC (f2::BASE_HIGH, EVENT FLAGS2); on the pad (no light yet this power cycle) and
//     the stand the lift is REFUSED with PC_SENSOR; the A1 relight proceeds on the measured P0. P0 < -kIgnBaseCheck_Pa (or no / no finite
//     P0) -> det::BASE_AMB: v2.11 (LEAD CHANGELOG 216 (4)) on the pad / stand the lift is REFUSED with PC_SENSOR as well (refusal before
//     the lift, MV closed by the abort); at the A1 relight P0 := 0 (ambient) and the start proceeds (v2.10; the bar is raised by the offset,
//     no false E2). v2.9 replaced P0 by ambient on BOTH sides (a positive offset then lowered the bar: false E2, probes B/C).
//   Light (E2) = filtered AND raw rise over P0 >= kIgnRise_Pa, with filtered AND raw Pc >= kIgnFloorAbs_Pa (absolute), for kIgnConfirmRelN
//     consecutive ticks after E1 (never before the lift).
// COMB: earliest light E1 + 0.079 s (liquid start; vapour-slug and post-purge starts later); unlit rise <= 0.44-0.51 bar (SIL cold-model
// bound), lit rise >= 1.38 bar (SIL A1) to 1.65 bar; margins unlit 0.29-0.45 bar, lit 0.58-0.85 bar; E2 14.0-15.5 ms after light.
// A pure offset after the zero cancels in the rise but not in the floor; the floor rises to 2.0 bar abs once B-PC-1 shows a residual
// <= 0.3 bar (kBpc1Shown, bench evidence). The legacy absolute rule stays selectable through EngineEcu::ign_detect_relative for
// comparison runs only (SIL/test; the flight build uses the constant below).
constexpr bool kIgnDetectRelative = true;          // [LEAD 2026-10-13]
constexpr int kIgnPreN = 20;                       // [LEAD/COMB] baseline over [E1 - 20 ms, E1] at 1 kHz
constexpr float kIgnRise_Pa = 0.80e5f;             // [LEAD/COMB] rise above P0, filtered AND raw
constexpr int kIgnConfirmRelN = 10;                // [LEAD/COMB] held 10 ms
#ifdef ECU_BPC1_SHOWN_VARIANT                      // v2.10 SIL-only second build for the S13 B extension (LEAD 166 (1): "both builds")
constexpr bool kBpc1Shown = true;
#else
constexpr bool kBpc1Shown = false;                 // [LEAD] true only after the B-PC-1 bench shows a post-zero residual <= 0.3 bar
#endif
constexpr float kIgnResidual_Pa = kBpc1Shown ? 0.30e5f : 0.60e5f;   // [LEAD B-PC-1 target / COMB present band] post-zero residual
// v2.12 (REV-ELEC-3 R3-01 item 4): the check also carries the zero drift from the latest accepted zero (re-zero2, or the ARM zero) to E1.
// With the seat compensation (option (b)) the residual drift re-zero2 -> E1 at k = 3 x typical is 0.027 bar (A1 relight) / 0.054 bar
// (stand relight after a B1-length burn) [DERIVED, calc/v2p12/c1_drift_v2p12.py A4] -> 0.06 bar. Uncompensated (coefficient not
// loaded: the flagged v2.11 fallback) the same term is 0.151 / 0.300 bar at k = 3 (0.851 / 0.551 bar needed) and, after a REJECTED
// re-zero, the ARM -> E1 drift 0.37-1.10 bar (A1) / 1.38-4.13 bar (stand) for k 1-3: not covered by any check (S13 T outcomes).
constexpr float kIgnBaseDrift_Pa = 0.06e5f;        // [DERIVED v2.12, compensated, k <= 3] zero drift latest accepted zero -> E1
constexpr float kIgnBaseCheck_Pa = kIgnResidual_Pa + kIgnBaseDrift_Pa + 0.10e5f;   // [LEAD form + R3-01 item 4] 0.76 / 0.46 bar
constexpr float kIgnFloorAbs_Pa = kBpc1Shown ? 2.0e5f : 1.8e5f;    // [LEAD/COMB] sanity floor, filtered AND raw, absolute
static_assert(kIgnPreN >= 1 && kIgnConfirmRelN >= 1 && kIgnitionConfirmN >= 1, "reference and confirmation counts");
static_assert(kIgnRise_Pa > kIgnBaseCheck_Pa - 0.25e5f, "rise threshold well above the baseline acceptance band");
// v2.9 drogue-release support (LEAD/GNC via coordinator 2026-10-13). The FC decides the release: at E2 AND [measured Pc >= 3.0 bar abs (Pc
// valid, no PC_SENSOR) OR the light-rule rise (filtered AND raw >= P0 + kIgnRise_Pa) held continuously from E2 to E2 + kDrogueRiseHold_s].
// The ECU publishes TLM_FAST d1 b4-b7 (tlmf::, 500 Hz) and EVENT STATE (RUN entry = E2, t_ms); it takes no drogue decision. GNC basis
// (coordinator): a 0.4 s hold after light costs P (-21/+6, p 0.006, 2 crashes), 0.1 s is neutral; the fuel-starved plateau can sit below
// 3.0 bar abs for up to 0.4 s.
constexpr float kDrogueRiseHold_s = 0.10f;         // [LEAD/GNC] rise-hold window after E2 for the FC release rule
// v2.10 R2 command hold (LEAD CHANGELOG 186 (2), OI-38, ADOPTED in design): while the drogue is attached with the Pc channel invalid, the
// open-loop command is held at the start level until the release. Reason (Combustion v2.4a cold_flow_thrust_v2p4a, DERIVED adiabatic
// bound): after an undetected flame-out the cold N2O flow alone gives 35.6-37.5 N of apparent thrust at a 200 N command and 12.5-13.3 N
// at the start level, against the 37.16 N R2 threshold. ECU rule (v2.11, LEAD 216 (9) / 230 (4); the v2.10 thrust-commanded form of this
// paragraph is SUPERSEDED, N-09): flight (not stand) AND state RUN AND drogue attached (FC Cmd::DROGUE arg 1, reset at power-up and ARM)
// AND Pc channel invalid this tick -> the pintle is commanded to kR2HoldLift_m exactly (LIFT-COMMANDED hold, below; the FC thrust command
// is only capped at kR2HoldThrust_N). It ends when the FC reports the release (Cmd::DROGUE arg 0), the Pc channel is valid again, or at
// the backstop E2 + kR2HoldBackstop_s; the command then returns bumplessly at <= kStartRamp_Nps. With Pc valid nothing changes (closed
// loop, A3 active). The ECU takes no drogue decision; the FC owns the release and the drogue state, and checks the echo (TLM_RELIGHT d6
// b6) before a RELIGHT. FLAMEOUT_OPT (FA-1 block above) covers a flame-out only after the main-chamber view is proven; at E2 it is not
// armed yet, which is the case this hold addresses. Tests: test_core (v210-17, v211 R2 rows); SIL S17 (in-loop FC stand-in with R2 and
// the cold-flow bound; lift-commanded hold at 0.21776 mm, Combustion v2.4b start-level lift [SIM]).
constexpr float kR2HoldThrust_N = 62.5f;           // [LEAD CHANGELOG 186 (2)] start level (12.5 % of 500 N); v2.11: kept only as the
                                                    //   ceiling of the FC command while the hold is on (the hold itself commands a LIFT)
static_assert(kR2HoldThrust_N > 0.0f && kR2HoldThrust_N <= 0.13f * 500.0f, "R2 hold at the start level (12.5 % of 500 N)");
// v2.11 (LEAD CHANGELOG 216 (9) R2-22, 230 (4), OI-43): the R2 hold is a LIFT-COMMANDED hold at Combustion v2.4b's start-level lift at the
// A1 relight state (Pc is invalid during the hold, so the thrust map adds nothing): the pintle command is kR2HoldLift_m exactly (servo rate
// limit only; no learned trim, no map), the setpoint and the start-ramp limiter are parked at the map equivalent so the return after the
// hold is bumpless at <= kStartRamp_Nps. CF-3 measures the cold flow at this lift with the encoder recorded (DESIGN, TO-VERIFY at CF-3).
constexpr float kR2HoldLift_m = 0.21776e-3f;        // [COMB v2.4b start-level lift at the A1 relight state, ECU hold-lift row, LEAD 230 (4)]
// v2.11 (LEAD CHANGELOG 216 (2)(b) R2-02 ADOPTED): ECU BACKSTOP - the hold ends no later than E2 + kR2HoldBackstop_s whatever the drogue
// report (a lost DROGUE 0 frame no longer holds a released, lit vehicle at the start level for the rest of the burn). Latched for the
// start; logged (LogRecord tlm_flags b2 R2_BACKSTOP, EVENT R2_BACKSTOP 0x24). Margin over the longer R2 v2 window (0.8 s, LEAD 227 (5)):
// 2 FC frames at the slowest FC-side period that carries the decision path (TLM_RELIGHT 50 Hz echo, 20 ms) + link latency 10 ms
// [ASSUMED: CAN frame + FC scheduling] = 50 ms. The FC's own ABORT at E2 + 0.8 s (dead engine) arrives before the backstop.
constexpr float kR2WindowMax_s = 0.80f;             // [LEAD CHANGELOG 227 (5)] longer R2 v2 confirmation window (W10 < 6 m/s)
constexpr float kFcFramePeriod_s = 0.020f;          // [DESIGN] TLM_RELIGHT period (d6 b6 echo the FC checks)
constexpr float kFcLinkLatency_s = 0.010f;          // [ASSUMED] CAN frame + FC scheduling bound
constexpr float kR2HoldBackstop_s = 0.85f;          // [DESIGN, LEAD 216 (2)(b)] E2 + 0.8 s + 50 ms
static_assert(kR2HoldBackstop_s >= kR2WindowMax_s + 2.0f * kFcFramePeriod_s + kFcLinkLatency_s - 1e-6f,
              "R2 backstop >= the 0.8 s window + 2 FC frames + link latency (LEAD 216 (2)(b))");
// FC rule (LEAD 216 (2)(a), FC owner: GNC; stated here for the interface): after DROGUE 0 the FC re-sends DROGUE 0 with a NEW sequence
// number (protocol.cpp seqOk rejects a pure retransmission) on every TLM_RELIGHT frame (50 Hz) that still shows d6 b6 = 1, starting with
// the second such frame after the first send, at most kFcDrogueResendMax times (bound 0.2 s); with b6 still 1 after that the FC logs a
// DROGUE_ECHO fault. The ECU backstop bounds the hold independently.
constexpr int kFcDrogueResendMax = 10;              // [DESIGN, FC side] 10 re-sends x 20 ms = 0.2 s

// ---------------------------------------------------------------- v2.9 coast re-zero of Pc and P_torch (Electronics DESIGN, LEAD to confirm)
// The OI-12 vented check (|Pc gauge| < kPcVentedMax_Pa = 0.1 bar) and the torch gate run on the ARM auto-zero. A zero drift after ARM
// above 0.1 bar makes a vented chamber read "not vented". v2.12 basis (REV-ELEC-3 R3-01, N-09; the v2.9 070BG basis of this paragraph
// is SUPERSEDED for Pc): the flight Pc transducer is C1 (Kulite XTL-190SM-2000A, seat-mounted): thermal zero 1 %FS / 100 F typical =
// 0.0248 bar/K [DATASHEET], maximum MISSING (F-10, k = max / typ swept 1-3); seat rise from ARM (Mechanical c1_seat_v352, diaphragm
// point) 0.80 K at re-zero1 / 12.53 K at re-zero2 / 14.53 K at E1 on the A1 relight and 22.0 / 50.4 / 54.4 K on the stand relight after
// a B1-length burn [SIM]: 0.30 bar is passed at k >= 0.95 (A1 re-zero2) and k >= 0.23 (stand) uncompensated. v2.12 adopts option (b)
// (LEAD 11:25Z working basis): the reading is seat-compensated first (EngineEcu::seatCompStep, kPcSeat* below) and kPcRezeroMax_Pa
// 0.30 bar acts on the compensated residual (A1 <= 0.185 bar, stand <= 0.551 bar at k 3; stand accepted at k 1 only with the +0.1 bar
// terms [DERIVED, calc/v2p12/c1_drift_v2p12.py]). Re-zero in COAST once the chamber has vented through the open throat (nozzle open,
// NC valve closed, pintle seated): mean of kPcRezeroN ticks from kPcRezeroFrom_s after COAST entry, accepted only if steady (filtered
// span <= kPcRezeroSpan_Pa) and within kPcRezeroMax_Pa of the ARM zero (a larger shift = sensor or chamber anomaly: keep the ARM zero).
// The torch transducer (070BG) has its OWN limit kPtorchRezeroMax_Pa (v2.12, below).
constexpr bool kPcCoastRezero = true;              // [DESIGN v2.9, LEAD to confirm]
constexpr float kPcRezeroFrom_s = 1.0f;            // [DESIGN] COAST entry + 1 s: chamber vent time constant ~0.04 s (DERIVED order of
                                                   //   magnitude: free volume / (throat flow at ~1 bar)); post-burn outgassing ~0.05 bar
constexpr int kPcRezeroN = 200;                    // [DESIGN] 0.2 s average (noise 1.7 kPa rms -> 0.12 kPa)
constexpr float kPcRezeroSpan_Pa = 0.05e5f;        // [DESIGN] filtered max - min over the block (a decaying chamber is not a zero)
constexpr float kPcRezeroMax_Pa = 0.30e5f;         // [LEAD 2026-10-13 B-PC-1 target] largest accepted shift from the ARM zero
static_assert(kPcRezeroMax_Pa > kPcVentedMax_Pa, "the re-zero exists to absorb drifts the vented check would refuse");
// v2.12 (REV-ELEC-3 R3-01 item 7): TORCH re-zero limit on the 070BG basis: TEB 1.05 bar over -20..85 C (~0.010 bar/K if linear)
// [DATASHEET as quoted in pc_transducer_v3]; torch-port rise from the head contribution only (Mechanical torch_port_bl08_v352, ARM ->
// re-zero2): 12.77 K (A1) -> 0.128 bar, 51.69 K (stand after B1) -> 0.517 bar [DERIVED]; + B-PC-1 zero drift 0.05 bar (ASSUMED) -> 0.57
// -> 0.60 bar. NOT covered (MISSING): torch heat into the port and the 070BG's own temperature (local heat; upper bracket: the 85 C band
// edge, TEB change <= 2.1 bar). A larger accepted torch zero only raises the torch-lit gate (late / no E1: TORCH_FAULT direction); E1
// stays 2oo2 with the photodiode.
constexpr float kPtorchRezeroMax_Pa = 0.60e5f;     // [DERIVED v2.12] largest accepted torch re-zero shift from the torch ARM zero
// v2.10 (LEAD REV-ELEC-1 RE-07, CHANGELOG 166 (5)): SECOND re-zero ending before the PURGE command. After the first block the ECU keeps
// averaging consecutive kPcRezeroN-tick quiet blocks through the coast (same quiet conditions); at an accepted PURGE or RELIGHT command in
// COAST the latest complete block is applied if it ended within kPcRezero2MaxAge_s, is steady (kPcRezeroSpan_Pa) and lies within
// kPcRezeroMax_Pa of the PAD (ARM) zero; it is applied BEFORE the vented check of that command. Otherwise the zero is kept
// (f2::REZERO2_REJ). NOT_VENTED: refusal on the stand and on the pad first start; in flight a flag to the FC (f2::NOT_VENTED) and the
// relight proceeds (also through the PREPRESS and PURGE -> IGNITION vented waits). The 20 s drift and zero TC are B-PC-1 measurements.
constexpr float kPcRezero2MaxAge_s = 0.50f;         // [DESIGN] the applied block ended at most this long before the command
// v2.12 C1 SEAT COMPENSATION (REV-ELEC-3 R3-01 option (b); LEAD 2026-10-21T11:25Z working basis; the LEAD confirms or changes it at the
// handback). Sensor: a seat TC on the MAX31856 #4 channel (no new IC, no new pin; re-assigned from the v2.7 bore-top TC, whose CF-3 / T1
// C7 evidence moves to the stand DAQ), at the head-top surface by the C1 boss (Mechanical sensor node r 25.875 mm, z = zt: within 0.24 K
// of re-zero2-referenced drifts; head-top node vs diaphragm gradient -0.29 / -0.73 / -0.69 K (A1 re-zero1 / re-zero2 / E1) [SIM]).
// Coefficient: the per-serial B-PC-1 table value (calibration, EngineEcu::setPcSeatCoef). Residual budget (k = 3, eps 10 % of the
// coefficient, TC lag 0.25 s, TC +/-0.3 K, gradient): A1 ARM -> re-zero2 0.185 bar, re-zero2 -> E1 0.027 bar; stand 0.551 / 0.054 bar
// [DERIVED]. The case TCs TC1 / TC2 cannot serve (fitted predictor error up to 10.2 K on B1 [DERIVED]). Fallback: coefficient 0 or no
// seat reference -> the v2.11 behaviour, flagged (f3::SEAT_COMP clear / f3::SEAT_NOREF).
constexpr float kPcSeatCoefMax_PaPerK = 1.0e4f;    // [DESIGN] |coef| bound (0.10 bar/K = 4 x the 0.0248 typical; a table value beyond = error)
constexpr float kPcSeatTcMin_K = 223.15f;          // [DESIGN] plausible seat TC range (-50 .. 200 C)
constexpr float kPcSeatTcMax_K = 473.15f;
constexpr float kPcSeatDevMax_K = 150.0f;          // [DESIGN] largest plausible seat rise from ARM (SIM stand max 93 K at S + 300 s) -> beyond = held
constexpr float kPcSeatRefMinFrac = 0.5f;          // [DESIGN] valid seat TC samples needed over the ARM auto-zero window
// v2.12 ARM sanity static term (kPcArmZeroMax_Pa): the bench zero (XdcrCal::offset_Pa) holds at the B-PC-1 zero temperature T_cal;
// at ARM the seat is at the soak temperature T0, so the check uses gauge - coef x (T_seat - T_cal) when the coefficient is set and
// the seat TC is valid and within kPcSeatArmDevMax_K of T_cal (else the v2.11 check).
constexpr float kPcSeatTcalDefault_K = 293.15f;    // [ASSUMED] B-PC-1 zero temperature until the per-serial record (setPcSeatTcal)
constexpr float kPcSeatTcalMin_K = 283.15f;        // [DESIGN] B-PC-1 bench zero 10 .. 35 C
constexpr float kPcSeatTcalMax_K = 308.15f;
constexpr float kPcSeatArmDevMax_K = 30.0f;        // [DESIGN] |T_seat - T_cal| at ARM beyond this -> no static term (flight T0 0-40 C,
                                                   //   T_cal 10-35 C: <= 30 K)
static_assert(kPcSeatCoefMax_PaPerK > 3.0f * 0.0248e5f && kPcSeatDevMax_K > 93.1f && kPcSeatTcMin_K < kPcSeatTcMax_K, "seat compensation bounds");
static_assert(kPcSeatTcalMin_K <= kPcSeatTcalDefault_K && kPcSeatTcalDefault_K <= kPcSeatTcalMax_K && kPcSeatArmDevMax_K >= 25.0f,
              "seat T_cal bounds");
// v2.10 (REV-ELEC-1 RE-19) MV switch + P_mid ladder: OPEN+CLOSED decodes invalid and raises Inputs::mv_sw_conflict -> fault MV after
// kMvSwConflictTime_s (stand and ARM: MV_FAULT; flight: flag, as the other MV-switch anomalies); the soft-short region below the
// lowest window is invalid; the pad BIT adds a harness-resistance step: on every BIT step the raw ladder ratio must sit within
// kLadderBitTol of the nominal ratio of the expected code (decoded switches + expected P_mid). Leak sensitivity (DERIVED from the
// ladder values): OPEN-state code detects a parallel leak up to ~300 kOhm, CLOSED-state ~500 kOhm (the 71-122 kOhm code flips
// found by REV-ELEC-1 R7 are inside). Bench: decade-box test (bench plan B-BLEED-1).
constexpr float kMvSwConflictTime_s = 0.005f;      // [DESIGN]
constexpr float kLadderBitTol = 0.006f;            // [DESIGN] about 1/3 of the 0.0193 minimum window gap; 1 % parts give ~0.003

// ---------------------------------------------------------------- v2.9 head-end bleed PROVISION (A1 forced purge)
// LEAD 2026-10-13 A1 RELIGHT CONFIGURATION (2): the head-end bleed is a DESIGNED-IN PROVISION for A1 in forced-purge form - T4 port
// (existing S12 plug location), 0.6-0.8 mm orifice, two NC SEG-P-rated valves in series (V1 upstream at T4, V2 downstream, stuck-open
// protection), airframe overboard port (ICD), ECU channels reserved. FITTED for A1 unless CF-4 shows the segment void below the zero-
// abort limit (18.86 cm3, wet and dry, ARM-hot case); not fitted for B1/B2/C/D (no in-flight relight). v2.12 (REV-COMB-4 R4-13): the
// purge-duration basis is Combustion purge_duration_v2p4.json (1ff6bfcd7d2f454c; combustion.json v2.4d 7dbf425c12300658): 1.9 s at
// 289.5 K and 2.2 s at 283.15 K on the decided 2 x 0.707 mm path (the superseded purge_sizing_v2p4.json 00955c206987e5e8 is no
// longer cited). Common-mode check (decided path, N-09): restrictors 2 x 0.707 mm UPSTREAM of V1 (at the taps); P_mid between V1 and
// V2 = a Kulite XTL-190SM-2000A (C1, J511, LEAD 206 (3)) on its INA333 chain -> U570 comparator (trip 11.085 / release 10.069 bar abs,
// DERIVED) -> one branch of the MV switch ladder on Teensy pin 23 (HAL decodes Inputs::pmid_hi, pmid_valid). With both valves open
// P_mid is ~0.06 x P_feed (about 3 bar abs, below the U570 band); the fill step (V1 open, V2 closed) is the path proof. Mid volume
// (seats + tee + transducer port) <= 0.5 cm3 (vent time, ICD on Mechanical).
// Electronics cannot see the bleed any other way: at 20 g/s the feed-line loss changes by 0.016 bar (dp 2.5 bar at 0.25 kg/s ~ mdot^2;
// the 170BG TEB is 2.55 bar) and there is no per-channel coil current sense (an open-load check would prove the coil, not the seat).
//   Pad BIT (PREPRESS, first start, feed primed, before IGNITION; kHbleedBitStep_s per step, comparator stable for the last
//   kHbleedBitSettleN ticks of each step): S0 V2 open -> P_mid low (else V1 stuck open / V2 failed closed); S1 both closed -> low
//   (else V1 leaks); S2 V1 open -> high (else V1 failed closed or P_mid chain dead); S3 both closed -> stays high (else V2 leaks);
//   S4 V2 open -> low (else V2 failed closed). Any failure -> BLEED_FAULT abort. One stuck-open valve fails S1 or S3.
//   PURGE (state 6; v2.10 schedule on FLOW time, LEAD CHANGELOG 164 (1)-(2)): entered from COAST by Cmd::PURGE (FC pre-scheduled at
//   E0 - kPurgeRelight_s = E0 - 2.90 s; LEAD 186 (1): the FC commits iff the lead to the plain relight trigger is >= L* = 1.3 s (an FC
//   parameter; 175 (3)/181 (2) interim 1.7 s replaced), else NO purge AND no relight on that pass (drogue descent); the v2.9
//   sequence-integrated purge on a bare RELIGHT is DELETED), only on
//   the direct path (directRelightOk). NC valve latch + opener ramp (rule b), pintle commanded seated. FILL STEP (v2.10): V1 opens at
//   entry with V2 CLOSED, so P_mid = P_feed with no flow whatever the restriction position (the decided path puts a 0.707 mm restrictor
//   at EACH TAP, i.e. UPSTREAM of V1, so the v2.9 'P_mid high with both valves open' proof is no longer physical): P_mid read high for
//   kHbleedConfirmN ticks = path and P_mid chain proven. V2 opens at kPurgeFlowStart_s - kHbleedOpenTime_s once the NC valve OPEN switch
//   was seen and the segment showed primed; a path not proven by then holds V2 for kHbleedPathBy_s more and then opens it with the flag
//   (flight) / BLEED_FAULT abort (stand). FLOW time (LEAD: both valves open -> closed) is DERIVED from the command times and the
//   measured valve times: flow start = V2 open command + kHbleedOpenTime_s, flow end = V1 close command + kHbleedCloseTime_s; the V1
//   close command is issued kPurgeFlow_s - kHbleedCloseTime_s after the flow start, so the flow ends kPurgeFlowEndLead_s before the
//   scheduled E0. The ECU never truncates the flow for T_fire: a RELIGHT before the purge is complete waits (purge_ign_); IGNITION
//   needs flow end + kPurgeFlowEndLead_s, V2 commanded closed, feed primed, chamber vented. The achieved flow time goes to the FC
//   (EVENT PURGE_FLOW, arg ms; log purge_flow_ms); the FC owns the T_fire decision (flow < kPurgeFlowMin_s -> FC delays T_fire, LEAD).
//   Firmware hard cap: both valves commanded open together for more than kHbleedCap_s (v2.11: 2.55 s, LEAD 203 (3); v2.10 2.61 s) -> both close
//   at once (EV_CAP, fault MV). Hardware (schematic v2.5, LEAD CHANGELOG 166 (3)): each bleed gate drive is ANDed (U574 V1, U575 V2,
//   separate ICs) with PURGE_WIN = FC discrete PURGE_EN (J512) AND a non-retriggerable one-shot (LTC6993-1, rising edge of PURGE_EN,
//   kHbleedHwWindowNom_s), so neither valve can be powered outside an FC-opened, time-limited window, whatever pin 15 (shared with the
//   heater permit) or pin 24 do. The window bounds the POWERED span from PURGE_EN (fill step + flow + vent), not the both-open overlap:
//   the both-open cap (v2.11 2.55 s) is the firmware function; v2.11 adds the hardware both-commanded-open timer (kHbleedHwBoth*, below).
//   The ECU cannot read PURGE_WIN (no free pin): the FC raises PURGE_EN for the pad BIT too, and a missing window fails BIT S2 (V1 not
//   opening) -> BLEED_FAULT abort on the pad. B1 build: J512 not fitted (bleed not fitted).
//   Post-flow hold (v2.10): bleed CLOSED, NC valve latched; no RELIGHT by the scheduled E0 + kPurgeHoldMax_s -> purge expired, COAST.
//   CLOSURE CONFIRMATION (v2.10, LEAD CHANGELOG 164: define the signal exactly). Signal: the P_mid comparator bit (v2.11/v2.12: U570 on
//   the C1 P_mid chain, trip 11.085 / release 10.069 bar abs, MV ladder pin 23, Inputs::pmid_hi with pmid_valid; the v2.10 LMV331 /
//   170BG levels are SUPERSEDED, N-09). Sequence from the V1 close command t_c (V2 still open):
//   (1) VENT: V2 close command at t_c + kHbleedCloseTime_s once P_mid has read LOW (valid) for kHbleedConfirmN consecutive ticks, else
//       at t_c + kHbleedCloseTime_s + kHbleedVentMax_s with vent_ok = false (mid trapped high: V1 stuck open at a high flowing P_mid,
//       or V2 failed closed / vent blocked);
//   (2) HOLD TEST: for kHbleedHoldTest_s after the V2 close command P_mid must stay LOW and VALID; kHbleedConfirmN consecutive ticks
//       high or invalid -> hold_ok = false (a V1 that did not shut re-pressurises the trapped mid volume behind the closing V2).
//   CONFIRMED iff the chain was proven in this purge (fill step) AND vent_ok AND hold_ok: V1 is shut against P_feed. It does not prove
//   V2 (a V2 stuck open stays latent until the next pad BIT; with V1 shut there is no flow). NOT CONFIRMED -> BLEED_FAULT to the FC
//   (fault bit MV, EVENT HBLEED EV_NOT_CLOSED, log hb2 reason bits): FLIGHT relight PROCEEDS (LEAD 2026-10-13 item 6; v2.9 aborted);
//   STAND keeps the v2.9 BLEED_FAULT abort (ground test of the detection, CF-4 P6; Electronics choice, LEAD to confirm). The lift never
//   waits for the result (it does not change the action) but is never commanded while a bleed valve is commanded open (hbLiftClear).
//   Leak monitor (both commanded closed, outside the closure step): P_mid high for kHbleedLeakTime_s -> V1 passing with V2 shut (or both
//   open): flight flag + EVENT (burn continues; the Pc loop absorbs the ADDITIVE 31.24 g/s, COMB CHANGELOG 163), stand BLEED_FAULT abort.
//   A V2 leak with V1 shut is invisible in flight (latent until the next pad BIT).
constexpr bool kHbleedFitted = false;              // [LEAD 2026-10-13] build value: A1 true (unless CF-4 clears it), B1/B2/C/D false
constexpr float kPurgeRelight_s = 2.90f;           // [LEAD CHANGELOG 164 (2)] PURGE command -> scheduled E0 (v2.9: 2.5 s = t_purge,
                                                   //   valves open the whole time; v2.10 = MV ramp + FLOW + end lead, below)
// v2.12 PURGE FINAL (LEAD CHANGELOG 253 (7)(ii), 256 (2), 257 (2), 258 (2); combustion.json v2.4d purge_decision_v2p4c): scheduled FLOW
// 2.43 s with the both-open cap 2.39 s. Both are CALIBRATION constants (EngineEcu::setPurgeCal): the values below are the DEFAULTS and the
// MAXIMA. RULE (d), re-set after CF-4 / B-BLEED-1: CF-4 / B-BLEED-1 measure the N2O Cd x A of the two-tap path and the valve times;
// cap <= 76 g / mdot(297.15 K) - (t_close - t_open), mdot at the warm end from (d1) the UPPER 95 % BOUND of the measured Cd x A (not its
// mean); flow = cap + t_close - t_open - 2 ticks at most (the scheduled command span ends >= 2 ticks before the cap); never above
// 2.43 / 2.39 s; (d2) CF-4 shows the 283.15 K need at the re-set flow (need and limit both scale with 1 / (Cd x A), ASSUMED). PURGE
// command at E0 - kPurgeRelight_s = E0 - 2.90 s (kept): flow start 0.42 s after PURGE (fill step, MV ramp 0.35 s), flow end E0 - 0.05 s.
// Vented mass [DERIVED]: scheduled 2.43 s -> 71.1 g at 29.25 g/s (289.5 K basis) / 75.5 g at 31.06 g/s (297.15 K); at the cap (flow
// 2.44 s) 71.4 / 75.8 g. Need (Combustion purge_duration_v2p4.json 1ff6bfcd7d2f454c): 1.9 s at 289.5 K, 2.2 s at 283.15 K, 1.8 s at
// 297.15 K: margin 0.23 s at 283.15 K.
constexpr float kPurgeFlow_s = 2.43f;              // [LEAD 256 (2) / 257 (2)] scheduled FLOW time: default AND maximum of the calibration
constexpr float kPurgeFlowMin_s = 1.9f;            // [COMB CHANGELOG 163, LEAD 164 (2)] FC planning floor at 289.5 K (2.2 s at 283.15 K,
                                                   //   LEAD 256 (2)(a)); reported, not enforced here
constexpr float kPurgeFlowCalMin_s = 1.0f;         // [DESIGN] sanity floor of a re-set flow (rule (d); the need scales with 1 / Cd x A)
constexpr float kPurgeFlowEndLead_s = 0.05f;       // [LEAD CHANGELOG 164 (1)] flow ends >= this before E0
constexpr float kHbleedOpenTime_s = 0.030f;        // [ASSUMED datasheet-class (SIL S12 'ds' case); B-BLEED-1 measures] command -> open
constexpr float kHbleedCloseTime_s = 0.080f;       // [ASSUMED datasheet-class 80 ms; LEAD CHANGELOG 164: S12 E0 -> flow stopped 77 ms
                                                   //   SIL on that valve model; B-BLEED-1 measures] command -> closed (flow stopped)
constexpr float kPurgeFlowStart_s = kPurgeRelight_s - kPurgeFlowEndLead_s - kPurgeFlow_s;   // [DERIVED] 0.42 s after PURGE (v2.11: 0.35 s)
// Both-open COMMAND cap (v2.12 FINAL 2.39 s, LEAD 256 (2) / 257 (2); v2.11 2.55 s, v2.10 2.61 s). The cap compares command times: the
// scheduled both-open command span F + t_o - t_c = 2.43 + 0.03 - 0.08 = 2.38 s (+ <= 1 tick) ends >= 2 ticks before it (static_assert).
// The limit is the VENTED MASS (LEAD 216 (5)); rule (d) above re-sets it after CF-4. Physical flow at the cap = cap + t_c - t_o = 2.44 s.
// HARDWARE both-commanded-open timer (LEAD 166 (3) / 216 (5), DESIGN, schematic v2.6 U576-U579, kHbleedHwBoth* below): drops V1
// at >= cap + 1 tick + tolerance, independent of firmware.
constexpr float kHbleedCap_s = 2.39f;              // [LEAD 256 (2) / 257 (2)] both-open command cap: default AND maximum of the calibration
static_assert(kPurgeFlow_s + kHbleedOpenTime_s - kHbleedCloseTime_s + 2.0f * kDt_s < kHbleedCap_s && kHbleedCap_s <= 2.39f + 1e-6f,
              "the scheduled both-open command span (F + t_o - t_c + 2 ticks) must end before the cap, cap <= 2.39 s (LEAD 256 (2))");
constexpr float kPurgeMdotBasis_kgps = 29.25e-3f;  // [LEAD 230 (3)] the ONE flow basis, 289.5 K (Combustion v2.4b)
constexpr float kPurgeMdotWarm_kgps = 31.06e-3f;   // [COMB v2.4b band warm end, 297.15 K; Cd ASSUMED]
constexpr float kPurgeVentLimit_kg = 0.076f;       // [LEAD 216 (5)] vented-mass limit
static_assert(kPurgeMdotWarm_kgps * (kHbleedCap_s + kHbleedCloseTime_s - kHbleedOpenTime_s) <= kPurgeVentLimit_kg,
              "rule (d) at the defaults: physical flow at the cap (2.44 s) within 76 g at the 297.15 K warm end (75.8 g)");
static_assert(kHbleedCap_s <= kPurgeVentLimit_kg / kPurgeMdotWarm_kgps - (kHbleedCloseTime_s - kHbleedOpenTime_s) + 1e-4f,
              "rule (d): cap <= 76 g / mdot(297.15 K) - (t_close - t_open) = 2.397 s");
// v2.11 (LEAD CHANGELOG 203 (7) ADOPTED; 186 (1), 204 (2)): FLIGHT with the head-end bleed fitted, a RELIGHT/IGNITE received in COAST (no
// purge running) is REFUSED (refuse::UNPURGED): the only accepted flight relight is the RELIGHT received during PURGE. The stand keeps
// the unpurged start (CF-4/T4 measure it); a build without the bleed fitted has no purge and keeps the v2.10 relight paths (LEAD to rule).
constexpr bool kUnpurgedRelightGuard = true;       // [LEAD 203 (7)]
constexpr float kHbleedVentMax_s = 0.030f;         // [DESIGN] extra vent allowance after V1's closing time (decided path: no restriction
                                                   //   downstream of V2, V2 >= 4x the restriction capacity: <= 0.5 cm3 mid vents in ms,
                                                   //   order-of-magnitude DERIVED; B-BLEED-1 measures)
constexpr float kHbleedHoldTest_s = kHbleedCloseTime_s + 0.020f;   // [DESIGN] V2 closing + refill of <= 0.5 cm3 at 31 g/s (<= 12 ms
                                                   //   DERIVED, liquid) + comparator ticks
constexpr float kPurgeHoldMax_s = 0.50f;           // [DESIGN; v2.10 redefined] post-flow hold with the bleed CLOSED, from the scheduled E0
                                                   //   (v2.9: 2.0 s with the valves OPEN, up to 4.5 s - retired). Combustion's tolerance
                                                   //   of a later E0 (static soak after the flow) is UNKNOWN: the decided basis is 0.05 s
constexpr float kHbleedPathBy_s = 0.10f;           // [DESIGN] extra wait for the fill-step path proof before V2 opens anyway (flag)
constexpr float kHbleedCloseConfirm_s = kHbleedCloseTime_s + kHbleedVentMax_s + kHbleedHoldTest_s;   // [DERIVED] closure step bound
constexpr int kHbleedConfirmN = 5;                 // [DESIGN] consecutive ticks of P_mid low (vent) / high (path, hold-test failure)
constexpr float kHbleedLeakTime_s = 0.20f;         // [DESIGN] P_mid high with both valves commanded closed
