static_assert(kPurgeFlowStart_s + 1e-4f >= kMvOpenRampSlow_s, "the flow starts once the NC valve opener ramp has run (2.90 = 0.42 + 2.43 + 0.05)");
static_assert(kPurgeFlow_s >= kPurgeFlowMin_s, "scheduled flow below the Combustion floor");
static_assert(kPurgeFlowStart_s > kHbleedOpenTime_s && kPurgeFlow_s > kHbleedCloseTime_s, "schedule ordering");
static_assert(kHbleedVentMax_s < kPurgeFlowEndLead_s, "V2 is commanded closed before the scheduled E0 (vent allowance < end lead)");
static_assert(kPurgeRelight_s > kMvOpenRampSlow_s + kHbleedPathBy_s, "the fill step and the MV-open check fit before the flow");
// v2.10 hardware purge window (schematic v2.5 U572 LTC6993-1; documentation of the hardware, not used by the code). The window starts
// at PURGE_EN rising and must cover the scheduled powered span: V2 close command <= flow start + kHbleedPathBy_s (path-proof delay)
// + kPurgeFlow_s - kHbleedCloseTime_s (V1 close command) + kHbleedCloseTime_s + kHbleedVentMax_s, plus the FC lead of PURGE_EN
constexpr float kFcPurgeEnLead_s = 0.020f;          // [ASSUMED, ICD item] FC raises PURGE_EN <= 20 ms before Cmd::PURGE, drops it at E0
constexpr float kHbleedHwWindowNom_s = 3.146f;      // [DESIGN] RSET 75.0 kOhm 0.1 %, DIVCODE 7 (R1 1.00M / R2 887k, NDIV 2^21, POL 0): 2.097152 x 75/50 s
constexpr float kHbleedHwWindowErr = 0.031f;        // [DATASHEET LTC6993 Rev F: NDIV >= 512 max 2.3 % (25 C) / 3.0 % (grade range); + 0.1 % RSET]
constexpr float kHbleedHwPoweredMax_s = kPurgeFlowStart_s + kHbleedPathBy_s + kPurgeFlow_s + kHbleedVentMax_s + kFcPurgeEnLead_s;   // [DERIVED] 3.00 s
static_assert(kHbleedHwWindowNom_s * (1.0f - kHbleedHwWindowErr) >= kHbleedHwPoweredMax_s, "hardware window shorter than the scheduled powered span");
// v2.11 HARDWARE BOTH-COMMANDED-OPEN TIMER (LEAD 166 (3), 216 (5); DESIGN, schematic v2.6 U576-U579 (v2.12: the cap comment above said
// U576-U578, N-09); documentation of
// the hardware, not used by the code; SIL sim.cpp hb_both_timer). BOTH = V1 drive AND V2 drive (U576 74LVC1G08 on the outputs of U574 / U575,
// i.e. after the PURGE_WIN gating). U577 LTC6993-2 (rising-edge, RETRIGGERABLE: each both-open episode is timed from its own start), POL 1,
// RSET 63.4 kOhm 0.1 %, DIVCODE 8 (POL 1 + NDIV 2^21 = R1 887k / R2 1.00M, VDIV/V+ 0.53125; DIVCODE 7 is POL 0; LTC6993 Rev F Table 1
// AS-RECALLED, TO-VERIFY before layout): T = 2.097152 s x 63.4 / 50 = 2.659 s. U578 74LVC1G74: CLK = U577 OUT (rises at the end of the pulse),
// D = BOTH, CLR_N = BOTH. U579 74LVC1G08 = U574 output AND /Q drives V1's gate: V1 drops when BOTH has been high for T_hw and stays off
// until a command drops (BOTH low clears U578). BOTH is taken BEFORE U579 (no self-clearing loop). V2 is untouched (the mid still
// vents). No MCU pin, no firmware path. The firmware
// cap acts first in every schedule (T_hw,min 2.577 s > cap + 1 tick 2.391 s, v2.12); the scheduled command span 2.38 s is never cut
// (T_hw,min). v2.12 option for the lead (not applied): RSET 59.0 kOhm -> 2.475 s nominal (2.398 s minimum) keeps T_min >= cap + 1 tick.
// Hardware residual (firmware cap failed): physical flow <= T_hw,max + t_c - t_o = 2.79 s -> 81.7 g at 29.25 g/s, 86.7 g at 31.06 g/s,
// 92.5 g at 33.13 g/s (Cd 0.80 ASSUMED) [DERIVED] instead of the PURGE_WIN bound 96-104 g. Not bounded: a command chattering faster than
// T_hw (the firmware cap has the same limit; PURGE_WIN still bounds it). The BIT sequence must not hold both open > 2.5 s.
constexpr float kHbleedHwBothNom_s = 2.659f;        // [DESIGN] RSET 63.4 kOhm E96 0.1 %, DIVCODE 8 (POL 1, NDIV 2^21)
constexpr float kHbleedHwBothErr = 0.031f;          // [DATASHEET LTC6993 Rev F, as kHbleedHwWindowErr: 3.0 % grade range + 0.1 % RSET]
static_assert(kHbleedHwBothNom_s * (1.0f - kHbleedHwBothErr) >= kHbleedCap_s + kDt_s,
              "hardware both-open timer (minimum) after the firmware cap + 1 tick: the firmware acts first, the schedule is never cut");

